const $ = (q, root=document) => root.querySelector(q);
const $$ = (q, root=document) => [...root.querySelectorAll(q)];
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = { health:null, route:'today' };
const suppliedToken = new URLSearchParams(location.search).get('token');
if (suppliedToken) { localStorage.setItem('radar-token', suppliedToken); history.replaceState(null, '', location.pathname + location.hash); }
const authToken = localStorage.getItem('radar-token');

async function api(path, options={}) {
  const headers = {'Content-Type':'application/json', ...(authToken?{'Authorization':`Bearer ${authToken}`}:{})};
  const response = await fetch('/api/v1'+path, {headers, ...options});
  if (!response.ok) throw new Error((await response.json().catch(()=>({}))).detail || `HTTP ${response.status}`);
  return response.json();
}
function age(value) {
  if (!value) return '';
  const h = Math.max(0, (Date.now()-new Date(value).getTime())/36e5);
  return h < 1 ? `${Math.max(1,Math.round(h*60))}m` : h < 48 ? `${Math.round(h)}h` : `${Math.round(h/24)}d`;
}
function toast(text) { const el=$('#toast'); el.textContent=text; el.classList.add('show'); setTimeout(()=>el.classList.remove('show'),1800); }
function header(kicker,title,sub,stats='') { return `<header class="page-head"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p class="subhead">${esc(sub)}</p></div>${stats}</header>`; }
function loading(){ $('#main').innerHTML='<div class="loading"><i></i><span>Scanning the horizon</span></div>'; }
function empty(msg){ return `<div class="empty">${esc(msg)}</div>`; }
function image(item){ return item.image_url ? `<img class="thumb" src="${esc(item.image_url)}" alt="" loading="lazy">` : `<div class="thumb blank">${esc((item.domain||item.type||'N')[0].toUpperCase())}</div>`; }
function card(item) {
  const score=item.score?.total!=null ? `${Math.round(item.score.total*100)} relevance` : '';
  const desc=item.summary||item.excerpt||item.repository?.description||'New signal detected by Radar.';
  return `<article class="story-card" data-id="${item.id}">${image(item)}<div>
    <div class="meta"><span class="tag">${esc(item.type.replaceAll('_',' '))}</span><span>${esc(item.source?.name||item.domain||'Radar')}</span><span>·</span><span>${age(item.published_at||item.first_seen_at)}</span>${item.cluster_id?`<span>· grouped</span>`:''}</div>
    <h3><a href="#/item/${item.id}">${esc(item.title)}</a></h3><p>${esc(desc)}</p><div class="reason">${esc(item.reason||score)}</div></div>
    <div class="card-actions"><button data-action="like" title="More like this" aria-label="Like">＋</button><button data-action="save" title="Save" aria-label="Save">◇</button><button data-action="dismiss" title="Dismiss" aria-label="Dismiss">×</button></div></article>`;
}
function projectCard(item){ const r=item.repository||{}; return `<article class="project"><div class="meta"><span class="tag">${esc(r.language||'project')}</span><span>${esc(r.license||'license unknown')}</span></div><h3><a href="#/project/${r.id}">${esc(r.full_name||item.title)}</a></h3><p>${esc(r.description||item.excerpt||'Discovered open-source project')}</p><div class="metrics"><span><b>${(r.stars??'—').toLocaleString?.()||r.stars}</b> stars</span><span><b>${r.stars_delta_7d??'—'}</b> / 7d</span><span><b>${r.mentions_7d??0}</b> mentions</span></div></article>`; }
function bindCards(){
  $$('.story-card button').forEach(btn=>btn.onclick=async e=>{ e.preventDefault(); const article=btn.closest('.story-card'), id=article.dataset.id, action=btn.dataset.action;
    try { if(action==='save') await api(`/items/${id}/save`,{method:'POST',body:'{}'}); else await api(`/items/${id}/feedback`,{method:'POST',body:JSON.stringify({action})});
      toast(action==='save'?'Saved':action==='like'?'Preference learned':'Hidden'); if(action==='dismiss') article.remove();
    } catch(err){ toast(err.message); }
  });
}
async function today(){ loading(); const d=await api('/digest?period=7d&limit=40&requested_by=ui'); const sections={for_you:'For you',important:'Important signals',adjacent:'Adjacent discoveries',oss:'Open source momentum',wildcard:'Wildcard'};
  const items=d.sections.flatMap(s=>s.items); $('#main').innerHTML=header('Daily intelligence','Your technology horizon','A focused mix of important movement, personal relevance, and deliberate exploration.',`<div class="stats"><div class="stat"><strong>${items.length}</strong><span>signals</span></div><div class="stat"><strong>${new Set(items.map(x=>x.source?.id).filter(Boolean)).size}</strong><span>sources</span></div></div>`)+
  (d.sections.map(s=>`<section class="section"><div class="section-title"><h2>${sections[s.key]||esc(s.key)}</h2><span>${s.items.length} items</span></div><div class="feed">${s.items.map(card).join('')}</div></section>`).join('')||empty('The first collection cycle has not produced a digest yet.'));
  bindCards(); }
async function explore(params={}){ loading(); const offset=params.offset||0, type=params.type?`&content_type=${encodeURIComponent(params.type)}`:''; const data=await api(`/items?sort=${params.sort||'newest'}&limit=100&offset=${offset}${type}`);
  $('#main').innerHTML=header('Manual mode','Explore everything','Browse the complete collected stream independently of recommendations.')+`<div class="toolbar"><button class="chip ${!params.type?'active':''}" data-type="">All</button><button class="chip" data-type="article">Articles</button><button class="chip" data-type="hackernews_post">HN</button><button class="chip" data-type="reddit_post">Reddit</button><button class="chip" data-type="youtube_video">Video</button><button class="chip" data-type="github_repository">Projects</button><button class="chip ${params.sort==='novelty'?'active':''}" data-sort="novelty">Sort: novelty</button></div><div class="feed">${data.items.map(card).join('')||empty('No collected items match this view.')}</div><div class="toolbar" style="justify-content:center;margin-top:20px">${offset?'<button class="action" id="prev-page">← Previous</button>':''}${data.items.length===100?'<button class="action" id="next-page">Next 100 →</button>':''}</div>`;
  bindCards(); $$('[data-type]').forEach(b=>b.onclick=()=>explore({type:b.dataset.type,sort:params.sort})); $('[data-sort]')?.addEventListener('click',()=>explore({type:params.type,sort:'novelty'})); $('#prev-page')?.addEventListener('click',()=>explore({...params,offset:Math.max(0,offset-100)})); $('#next-page')?.addEventListener('click',()=>explore({...params,offset:offset+100})); }
async function projects(){ loading(); const data=await api('/projects?limit=100'); $('#main').innerHTML=header('Open source','Project discovery','Repositories are analyzed with activity, growth, release, license, and cross-community signals.')+`<div class="toolbar"><button class="chip active">Momentum</button><button class="chip" id="proj-new">Newest</button><button class="chip" id="proj-stars">Stars</button></div><div class="project-grid">${data.projects.map(projectCard).join('')||empty('Projects will appear after the GitHub collectors run.')}</div>`; $('#proj-new').onclick=()=>projectSort('newest'); $('#proj-stars').onclick=()=>projectSort('stars'); }
async function projectSort(sort){ const data=await api(`/projects?sort=${sort}&limit=100`); $('.project-grid').innerHTML=data.projects.map(projectCard).join('')||empty('No projects.'); }
async function listMode(mode){ loading(); const data=await api(`/items?${mode}=true&sort=newest&limit=100`); $('#main').innerHTML=header(mode==='saved'?'Library':'Activity',mode==='saved'?'Saved intelligence':'Reading history',mode==='saved'?'Items kept for later investigation.':'Previously opened stories and projects.')+`<div class="feed">${data.items.map(card).join('')||empty(mode==='saved'?'Nothing saved yet.':'No reading history yet.')}</div>`; bindCards(); }
async function sources(){ loading(); const d=await api('/sources'); $('#main').innerHTML=header('Collection network','Sources','Seed, manual, and automatically discovered inputs with visible health.')+`<table class="source-table"><thead><tr><th>Source</th><th>Type</th><th>Status</th><th>Items</th><th>Last success</th><th></th></tr></thead><tbody>${d.sources.map(s=>`<tr><td><b>${esc(s.name)}</b><br><small>${esc(s.identifier)}</small></td><td>${esc(s.kind)}</td><td><span class="status ${esc(s.status)}">${esc(s.status)}</span></td><td>${s.item_count}</td><td>${age(s.last_success_at)||'—'}</td><td><button class="action source-toggle" data-id="${s.id}" data-status="${s.status==='active'||s.status==='trial'?'muted':'active'}">${s.status==='active'||s.status==='trial'?'Mute':'Activate'}</button></td></tr>`).join('')}</tbody></table>`; $$('.source-toggle').forEach(b=>b.onclick=()=>api(`/sources/${b.dataset.id}`,{method:'PATCH',body:JSON.stringify({status:b.dataset.status})}).then(()=>{toast('Source updated');sources();})); }
async function settings(){ loading(); const [ints,src]=await Promise.all([api('/interests'),api('/health')]); $('#main').innerHTML=header('Transparent controls','Settings & interests','Radar learns from explicit actions; exploration remains independently budgeted.')+`<section class="section"><div class="section-title"><h2>Interest model</h2><span>${ints.interests.length} topics</span></div><table class="source-table"><thead><tr><th>Topic</th><th>Weight</th><th>Evidence</th><th>Origin</th></tr></thead><tbody>${ints.interests.map(x=>`<tr><td><b>${esc(x.topic)}</b></td><td>${x.weight.toFixed(2)}</td><td>+${x.positive_evidence} / −${x.negative_evidence}</td><td>${x.seed?'seed':''}${x.learned?' learned':''}</td></tr>`).join('')}</tbody></table></section><section class="section"><div class="section-title"><h2>Local system</h2></div><aside class="project"><p>Database contains <b>${src.counts.items}</b> items from <b>${src.counts.sources}</b> sources and <b>${src.counts.projects}</b> projects. Processing stays on this machine.</p></aside></section>`; }
async function detail(id, isProject=false){ loading(); const d=await api(isProject?`/projects/${id}`:`/items/${id}`); const item=d.project||d.item, r=item.repository; const story=item.cluster_id?await api(`/stories/${item.cluster_id}`):null; const coverage=story&&story.story.sources.length>1?`<section class="section"><div class="section-title"><h2>Coverage</h2><span>${story.story.source_count} sources · ${story.story.item_count} reports</span></div><div class="feed">${story.story.sources.map(s=>`<article class="story-card" style="grid-template-columns:minmax(0,1fr) auto;min-height:0"><div><div class="meta"><span class="tag">${esc(s.type)}</span><span>${esc(s.source?.name||s.domain)}</span><span>· ${age(s.published_at||s.first_seen_at)}</span></div><h3>${esc(s.title)}</h3></div><a class="action" href="${esc(s.link_url||s.url)}" target="_blank" rel="noopener">Open ↗</a></article>`).join('')}</div></section>`:''; $('#main').innerHTML=`<article class="detail"><a class="eyebrow" href="javascript:history.back()">← Back</a><div class="hero"><div class="meta"><span class="tag">${esc(item.type)}</span><span>${esc(item.source?.name||item.domain)}</span><span>· ${age(item.published_at||item.first_seen_at)}</span></div><h1>${esc(item.title)}</h1><p class="subhead">${esc(item.summary||item.excerpt||r?.description||'')}</p><div class="toolbar"><a class="action" href="${esc(item.link_url||item.url)}" target="_blank" rel="noopener">Open original ↗</a><button class="action" id="detail-save">Save</button><button class="action" id="detail-like">More like this</button></div></div>${item.why_it_matters?`<aside><div class="eyebrow">Why it matters</div>${esc(item.why_it_matters)}</aside>`:''}${r?`<aside><div class="eyebrow">Repository signals</div><div class="metrics"><span><b>${r.stars??'—'}</b> stars</span><span><b>${r.stars_delta_7d??'—'}</b> growth / 7d</span><span><b>${esc(r.license||'unknown')}</b> license</span><span><b>${esc(r.language||'—')}</b> language</span></div></aside>`:''}${coverage}<section class="section"><div class="section-title"><h2>Source material</h2></div><div class="detail-body">${esc(item.content||item.excerpt||'Full text was not available; open the original source.')}</div></section></article>`; $('#detail-save').onclick=()=>api(`/items/${item.id}/save`,{method:'POST',body:'{}'}).then(()=>toast('Saved')); $('#detail-like').onclick=()=>api(`/items/${item.id}/feedback`,{method:'POST',body:'{"action":"like"}'}).then(()=>toast('Preference learned')); }
async function search(query){ loading(); const d=await api(`/search?q=${encodeURIComponent(query)}`); $('#main').innerHTML=header('Search',`Results for “${query}”`,'Lexical and semantic retrieval across every collected item.')+`<div class="feed">${d.results.map(card).join('')||empty('No matches found.')}</div>`; bindCards(); }
async function route(){ const [name,arg]=(location.hash.replace(/^#\//,'')||'today').split('/'); state.route=name; $$('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===name)); try { if(name==='today') await today(); else if(name==='explore') await explore(); else if(name==='projects') await projects(); else if(name==='saved'||name==='history') await listMode(name); else if(name==='sources') await sources(); else if(name==='settings') await settings(); else if(name==='item') await detail(arg); else if(name==='project') await detail(arg,true); else await today(); } catch(err){ $('#main').innerHTML=header('Connection issue','Radar is unavailable',err.message)+empty('Check that the local API service is running.'); } window.scrollTo(0,0); }
$('#search').addEventListener('keydown',e=>{ if(e.key==='Enter'&&e.target.value.trim()) search(e.target.value.trim()); });
document.addEventListener('keydown',e=>{ if(e.key==='/'&&document.activeElement!==$('#search')){e.preventDefault();$('#search').focus();} });
$('#theme').onclick=()=>{ document.documentElement.classList.toggle('light'); localStorage.setItem('radar-theme',document.documentElement.classList.contains('light')?'light':'dark'); };
if(localStorage.getItem('radar-theme')==='light') document.documentElement.classList.add('light');
window.addEventListener('hashchange',route); route();
api('/health').then(h=>{ state.health=h; $('#system-pill').classList.add('ok'); $('#system-pill span').textContent=`Local · ${h.counts.items} items`; }).catch(()=>$('#system-pill span').textContent='Offline');
